// The menu's strings (v0.9). Every string the menu shows has an id from
// lang/en.ini (lang_ids.h, generated by `just lang`), and code reads it as
// S(STR_...). English is compiled in (lang_en.c); a language pack from the
// card (/torii/lang/<code>.lng, tools/lang.py) sits in PSRAM, and any string
// it lacks, or a pack the kernel rejects, shows in English.
//
// Texts never go through printf: {1} to {9} are what the code fills in,
// with lang_fill or SF and the arguments below, so a translation puts them
// in its own order. Counts read SN(STR_..., n): the .one form for 1, the
// .other form for any other number.
//
// This file is hardware-free (tests/host); lang_load.c finds, checks and
// loads the packs on the cart.
#ifndef TORII_LANG_H
#define TORII_LANG_H

#include <gba_base.h>

#include "lang_ids.h"

// The string id names, in the active language (English for an id past
// STR_COUNT: "")
const char *S(u32 id);
// A count's form: id is a .one key's (STR_X), STR_X_OTHER follows it; SN
// reads it (SN(STR_X, n)), STR_N names it (SF(..., STR_N(STR_X, n), LN(n)))
#define STR_N(id, n) ((u32)(id) + ((n) != 1))
#define SN(id, n) S(STR_N(id, n))

extern const char *const lang_en[STR_COUNT];

// What a placeholder takes: built with the macros below
enum lang_arg_kind {
	LANG_ARG_NUM,     // n in decimal
	LANG_ARG_STR,     // s
	LANG_ARG_CUT,     // s cut to at most n bytes, on a whole character
	LANG_ARG_ZERO,    // n in decimal, zero-padded to width digits
	LANG_ARG_HEX,     // n in upper-case hex, zero-padded to width digits
	LANG_ARG_GROUP,   // n in decimal, its thousands apart ("1,204")
	LANG_ARG_TENTHS,  // n tenths, with the decimal separator ("1.5")
};
struct lang_arg {
	const char *s;
	u32 n;
	u8 kind;
	u8 width;
};
#define LN(x) ((struct lang_arg){NULL, (u32)(x), LANG_ARG_NUM, 0})
#define LS(x) ((struct lang_arg){(x), 0, LANG_ARG_STR, 0})
#define LCUT(x, max) ((struct lang_arg){(x), (u32)(max), LANG_ARG_CUT, 0})
#define LZ(x, w) ((struct lang_arg){NULL, (u32)(x), LANG_ARG_ZERO, (w)})
#define LX(x, w) ((struct lang_arg){NULL, (u32)(x), LANG_ARG_HEX, (w)})
#define LG(x) ((struct lang_arg){NULL, (u32)(x), LANG_ARG_GROUP, 0})
#define LT(x) ((struct lang_arg){NULL, (u32)(x), LANG_ARG_TENTHS, 0})

// Copies text into out (room bytes, cut on a whole UTF-8 character and
// ended), each {N} as args[N - 1] (a placeholder with no argument stays as
// it is). Returns the bytes written, without the NUL.
u32 lang_fill_args(char *out, u32 room, const char *text, u32 argc, const struct lang_arg *args);
#define LANG_ARGS(...) \
	(u32)(sizeof((const struct lang_arg[]){__VA_ARGS__}) / sizeof(struct lang_arg)), (const struct lang_arg[]) \
	{ \
		__VA_ARGS__ \
	}
#define lang_fill(out, room, text, ...) lang_fill_args((out), (room), (text), LANG_ARGS(__VA_ARGS__))
// lang_fill with the string id names
#define SF(out, room, id, ...) lang_fill_args((out), (room), S(id), LANG_ARGS(__VA_ARGS__))

// n with the language's thousands separator ("1,204"); returns its bytes
u32 lang_number(char *out, u32 room, u32 n);
// A day and month (1-12) as the language writes them: with the month's
// name ("28 Oct"), or in digits ("10-28")
u32 lang_date(char *out, u32 room, u32 day, u32 month);
u32 lang_date_numeric(char *out, u32 room, u32 day, u32 month);

// The game popup's items (screens/games.c), in [games]' pop_* order
enum {
	LANG_POP_PLAY,
	LANG_POP_FAV,
	LANG_POP_RENAME,
	LANG_POP_UNNAME,  // a game with a name of its own: back to its file's or No-Intro's
	LANG_POP_INFO,
	LANG_POP_SAVES,
	LANG_POP_CHEATS,  // a GBA game on the card: its cheat screen (screens/cheats.c), its count if it has a cheat file
	LANG_POP_STATES,  // a GBA game on the card, Save states on: start it in one of its save states (v0.8)
	LANG_POP_UNRECENT,  // the Recent page's Remove: off Recent, the file stays
	LANG_POP_DELETE,
	LANG_POP_ITEMS,
};
// How Play (Launch) starts a game, stepped in the popup with LEFT/RIGHT, in
// [games]' boot_* order
enum {
	LANG_BOOT_DEFAULT,  // the game's boot mode, else Settings' (A on the list)
	LANG_BOOT_CLEAN,
	LANG_BOOT_ADDONS,  // a GBA game with an addon on
	LANG_BOOTS,
};
// Game info's lines, in [games]' info_* order
enum {
	LANG_INFO_CONSOLE,
	LANG_INFO_SIZE,
	LANG_INFO_FOLDER,
	LANG_INFO_PLAYED,
	LANG_INFO_SAVE_TYPE,
	LANG_INFO_BOOT_MODE,
	LANG_INFO_HARD_RESET,
	LANG_INFO_KEYS,
};

// --- Packs ------------------------------------------------------------------

// A pack's header (tools/lang.py: its format); offsets follow it
#define LANG_HEADER 64
#define LANG_CODE_BYTES 8
#define LANG_NAME_BYTES 24
enum lang_pack_check {
	LANG_PACK_OK,
	LANG_PACK_SHORT,  // smaller than its header and offsets, or its size field
	LANG_PACK_MAGIC,  // not a pack
	LANG_PACK_STALE,  // another format, count or set of keys: built for another Torii
	LANG_PACK_CRC,  // damaged
	LANG_PACK_BAD,  // an offset past its strings, or strings with no end
	LANG_PACK_CHECKS
};
// Whether bytes at pack (a whole pack file) are a pack this kernel takes:
// LANG_PACK_OK, or why not
u32 lang_pack_check(const u8 *pack, u32 bytes);
// The same for its first LANG_HEADER bytes alone (a listing): its size,
// CRC and offsets wait for lang_pack_check
u32 lang_pack_check_header(const u8 *pack);
extern const char *const lang_pack_check_names[LANG_PACK_CHECKS];
// The pack's code ("sv") and name ("Svenska"), NUL-ended, from its header
void lang_pack_code(const u8 *pack, char out[LANG_CODE_BYTES]);
void lang_pack_name(const u8 *pack, char out[LANG_NAME_BYTES]);

// Strings from now on come from pack (checked whole by lang_pack_check),
// wherever it is (PSRAM, RAM): S reads it in place. NULL: English.
void lang_use(const u8 *pack);
// 1 while a pack is in use
int lang_using_pack(void);
// Copies the launch's strings (ids below STR_LAUNCH_END) of the pack in use
// into room (bytes long, word-aligned), and reads them there from now on;
// every other string shows in English. Returns 0 (and uses English) if
// they don't fit, which tools/lang.py's LANG_LAUNCH_MAX keeps from
// happening.
int lang_keep_launch(void *room, u32 bytes);

// Settings' id for a pack's code (English is LANG_ENGLISH_ID): never 0,
// 0xFFFF (an erased slot) or English's
u16 lang_code_id(const char *code);

// The languages Settings offers: English first, then the packs found on the
// card (lang_load.c), up to LANG_LIST_MAX
#define LANG_LIST_MAX 8
struct lang_choice {
	u16 id;  // lang_code_id
	char code[LANG_CODE_BYTES];
	char name[LANG_NAME_BYTES];
};
// English alone again
void lang_list_reset(void);
// Adds a pack's language; 0 if the list is full or has its id
int lang_list_add(const char *code, const char *name);
u32 lang_count(void);
const struct lang_choice *lang_choice(u32 i);
// The index of the language Settings stores as id: 0 (English) if none
u32 lang_index_of(u16 id);

// --- On the cart (lang_load.c) ----------------------------------------------

// The boot, once the card is mounted: the packs in /torii/lang, and the
// language Settings stores, loaded
void lang_boot(void);
// Loads choice i (lang_choice): its pack into PSRAM, or English. Returns 1
// if that language is now in use.
int lang_switch(u32 i);
// The index of the language in use
u32 lang_current(void);
// Before a launch fills PSRAM: the launch's strings to RAM
// (lang_keep_launch), in the row cache's room until the menu runs again
void lang_before_launch(void);
// The menu's loop: loads the pack again after a launch that came back
void lang_poll(void);

#endif
